# -*- coding: utf-8 -*-
from pathlib import Path
import json
from lesson_authoring import entry as E
BASE=Path(__file__).resolve().parents[1];OUT=BASE/'.cache/batch200/drafts/rewrite_spec'
T=[['拉丁 tacere','保持沉默、不说话']]
TC=T+[['拉丁 tacitus','不说出来的、默然的'],['法语 tacite／直接拉丁借入 → 英语 tacit','没有明说、但已暗含的']]
R=T+[['拉丁 re- + tacere → reticere','保持缄默；re- 在此常解释为加强语气']]
W=[E('tacit','/ˈtæsɪt/','心照不宣的；默示的；隐性的','嘴上没有说出来，意思却藏在行动或共同理解里。','借法语 tacite 或直接借拉丁 tacitus，后者是 tacere“保持沉默”的分词。意思从“不说话”延伸为“不明说却已暗含”。',TC,'Tacit agreement 是大家没有把话挑明，却形成了默契。Tacit knowledge 则常指做得出来、却难完整说成规则的经验，比如熟练师傅凭手感判断火候；不必理解成故意保密。','tacit agreement/approval/support；tacit knowledge。常放在名词前。','explicit 是明确说出；tacit 是未明说而暗含。某人单纯没讲话，并不能脱离情境就断定他同意。',('There was a tacit agreement that neither of them would mention the failed plan.','两人心照不宣，都不再提那个失败的计划。'),('The workshop helps experienced bakers pass on their tacit knowledge.','这个工作坊帮助有经验的面包师传授难以言明的实践经验。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/tacit','https://www.etymonline.com/word/tacit']),
E('tacitly','/ˈtæsɪtli/','默示地；不明说地；心照不宣地','没有直接说“是”，行动或安排却表达了那个意思。','英语 tacit + 副词后缀 -ly。前半追溯拉丁 tacere“保持沉默”，现代词用来修饰接受、承认、赞同等动作。',TC+[['英语 tacit + -ly → tacitly','以不明说、暗含的方式']],'Tacitly acknowledge 不是大声承认，而是做了让人看出承认的事。例如没有公开认错，却悄悄更正了数据。它强调表达方式，不等于偷偷摸摸。','tacitly accept/acknowledge/approve；tacitly agree；tacitly assume。','silently 只说明没有发出声音；tacitly 还表示某个意思被暗含了。偷偷行动则通常用 secretly。',('By quietly correcting the figures, the company tacitly acknowledged the error.','公司悄悄更正了数据，实际上默示承认了错误。'),('The two colleagues tacitly agreed to share the least popular duties.','两位同事心照不宣地分担了最不受欢迎的工作。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/tacitly','https://en.wiktionary.org/wiki/tacitly','https://www.etymonline.com/word/tacit']),
E('reticent','英 /ˈretɪsənt/；美 /ˈretəsənt/','不愿多谈的；有保留的；寡言的','话留在心里，不太愿意对外讲。','借拉丁 reticent-，来自 reticere“保持缄默”的现在分词。re- 在这里常看作加强，tacere 的 a 在复合形式里变为 i；不是现代 re- + tic 拼出来的。',R+[['拉丁 reticens，词干 reticent- → 英语 reticent','保持沉默的 → 不愿透露的']],'一个人平时很健谈，也可能 reticent about his plans：一谈自己的计划就不肯多说。它可以是性格，也可以只是对某个话题有所保留。','reticent about/on a subject；rather/extremely reticent。也可见 reticent to do 表示不愿做；若只是普通的犹豫，用 reluctant 更清楚。','taciturn 更常写一贯话少；reticent 常突出不愿把想法、经历或信息说出来。',('She was cheerful at dinner but reticent about her next job.','晚餐时她很愉快，却不愿多谈下一份工作。'),('The normally reticent engineer spoke at length about the new design.','那位平时寡言的工程师详细谈起了新设计。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/reticent','https://www.merriam-webster.com/dictionary/reticent','https://en.wiktionary.org/wiki/reticent']),
E('reticence','英 /ˈretɪsəns/；美 /ˈretəsəns/','缄默；不愿多谈；保留态度','不是没有东西可说，而是把话收住了。','现代与 reticent 成名词、形容词一对；历史上名词经法语 réticence 或直接接拉丁 reticentia，来自 reticere 的分词。英语名词早于 reticent，不能把借入链画反。',R+[['拉丁 reticens → reticentia','保持沉默的 → 缄默'],['法语 réticence／直接拉丁借入 → 英语 reticence','不愿多说、保留态度']],'Her reticence about the negotiations 表示她对谈判不肯透露太多，可能出于谨慎或保密，并不自动等于害羞。作为性格描述，则表示习惯少说。','reticence about/on something；natural reticence；overcome one’s reticence。通常作不可数名词。','silence 可以只是现场没声音；reticence 更关注一个人有所保留、不愿多谈的态度。',('His reticence about the negotiations frustrated the reporters.','他不愿透露谈判情况，让记者们感到懊恼。'),('Her initial reticence faded once the discussion turned to gardening.','话题转到园艺后，她起初不愿多谈的拘谨渐渐消失了。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/reticence','https://www.etymonline.com/word/reticence','https://en.wiktionary.org/wiki/reticence']),
E('taciturn','英 /ˈtæsɪtɜːn/；美 /ˈtæsɪtɜːrn/','沉默寡言的〔正式〕','这个人本来就话少，问一句往往只答一句。','远源是拉丁 taciturnus“少言的”，接 tacitus“沉默的”。英语有从较早名词 taciturnity 逆构、或从法语 taciturne 借入的分析；不能拆成 tacit + 英语 turn。',T+[['拉丁 tacitus → taciturnus','沉默的 → 不爱说话的'],['两条可能路线','法语 taciturne 借入；或拉丁 taciturnitas 经法语、英语 taciturnity 后逆构'],['英语 taciturn','沉默寡言的']],'它常在小说或人物描述里出现，写那种不大开口、显得冷淡的人。话少不等于没有感情，也不保证这个人是在隐藏秘密。','a taciturn man；a taciturn manner；quiet and taciturn。','tacit 修饰未明说的意思或安排；taciturn 修饰少言的人。a tacit agreement 与 a taciturn guide 不能互换。',('Our taciturn guide spoke only when we reached a difficult turn.','我们那位寡言的向导，只有走到难走的转弯处才开口。'),('The film reveals the warmth beneath the father’s taciturn manner.','电影展现了父亲寡言外表下的温情。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/taciturn','https://www.etymonline.com/word/taciturn','https://en.wiktionary.org/wiki/taciturn'])]
m=json.loads((BASE/'.cache/batch200/rewrite_spec.json').read_text());r=next(x for x in m['roots']if x['id']=='C1464');c=next(x for x in json.loads((BASE/'.cache/catalog.json').read_text())if x['id']=='C1464');keep={w['word']for w in W};excluded={w:'按用户当前范围暂略：更少见的同族抽象名词或派生词。'for w in(set(r['family'])|set(c['family'])|set(c.get('unmatched',[])))-keep}
ROOT=[dict(id='C1464',meaning='沉默；不说话',core='tac- 的画面是话没有说出口。',image='没明说却已有意思，是 tacit；不愿透露，是 reticent；一贯话少，是 taciturn。',intro='同样是“不说”，可能是彼此有默契、对某事保留，也可能单纯寡言。抓住不说话的方式和对象，比把几个词都背成“沉默的”有用。',forms='拉丁 tacere“沉默”与分词 tacitus；复合动词 reticere 中可见 -tic-，它不是普通英语名词 tic。',branches=[['不明说却暗含','tacit、tacitly'],['有所保留','reticent、reticence'],['沉默寡言','taciturn']],contrasts='reticence 的英语借入早于 reticent；taciturn 的后半也不是 turn“转动”。同族关系不等于现代英语里依次派生。',practice='想一个“大家心照不宣”的安排，再想一个“某人不肯多谈”的话题，分别用 tacit 和 reticent 描述。',words=[w for w in r['family']if w in keep],exclude=excluded,sources=['https://www.etymonline.com/word/tacit','https://www.etymonline.com/word/reticence','https://www.etymonline.com/word/taciturn'])]
assert all(w['word']in m['owned_words']for w in W)
assert not(set(c['family'])|set(c.get('unmatched',[])))-set(ROOT[0]['words'])-set(excluded)
for w in W:assert len(w['examples'])>=2 and all(len(n)==2 and all(isinstance(x,str)and x for x in n)for n in w['history'])
for k,d in [('roots',ROOT),('words',W)]: (OUT/f'{k}_batch200_spec_219_tac.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
print('C1464',len(W),'new')
